{"sql":"-- 1. Create role theme_analyst
DO $$
BEGIN
   IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'theme_analyst') THEN
      CREATE ROLE theme_analyst NOINHERIT LOGIN PASSWORD 'secure_password_here';
   END IF;
END
$$;

-- Grant SELECT on reference tables
GRANT SELECT ON lego_themes TO theme_analyst;
GRANT SELECT ON lego_colors TO theme_analyst;
GRANT SELECT ON lego_parts TO theme_analyst;
GRANT SELECT ON lego_part_categories TO theme_analyst;

-- Grant SELECT on main data tables
GRANT SELECT ON lego_sets TO theme_analyst;
GRANT SELECT ON lego_inventories TO theme_analyst;
GRANT SELECT ON lego_inventory_parts TO theme_analyst;"}

{"sql":"-- 2. Enable Row-Level Security (RLS) on main data tables
ALTER TABLE lego_sets ENABLE ROW LEVEL SECURITY;
ALTER TABLE lego_inventories ENABLE ROW LEVEL SECURITY;
ALTER TABLE lego_inventory_parts ENABLE ROW LEVEL SECURITY;"}

{"sql":"-- Recreate function get_user_theme_id before applying policy
CREATE OR REPLACE FUNCTION get_user_theme_id()
RETURNS INTEGER AS $$
BEGIN
   IF current_user = 'theme_analyst' THEN
      RETURN 18; -- Star Wars theme
   ELSE
      RETURN NULL; -- No theme assigned
   END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
"}

{"sql":"DROP POLICY IF EXISTS theme_inventory_parts_policy ON lego_inventory_parts;
CREATE POLICY theme_inventory_parts_policy ON lego_inventory_parts
FOR SELECT
USING (EXISTS (
  SELECT 1 FROM lego_inventories i
  JOIN lego_sets s ON s.set_num = i.set_num
  WHERE lego_inventory_parts.inventory_id = i.id
    AND s.theme_id = get_user_theme_id()
));"}

{"sql":"-- Verification Queries for theme_analyst role
SET ROLE theme_analyst;

-- 5. Test queries
-- Query 1: Lego sets for Star Wars theme (theme_id=18)
SELECT set_num FROM lego_sets WHERE theme_id = 18 ORDER BY set_num;

-- Query 2: Lego sets for Technic theme (theme_id=1), should return 0 rows
SELECT set_num FROM lego_sets WHERE theme_id = 1 ORDER BY set_num;

-- Query 3: Check inventories only for Star Wars theme by joining sets
SELECT i.id, i.set_num FROM lego_inventories i
JOIN lego_sets s ON s.set_num = i.set_num
WHERE s.theme_id = 18
ORDER BY i.id LIMIT 5;

-- Query 4: Check inventory parts only for Star Wars theme by joining inventories and sets
SELECT lip.inventory_id, lip.part_num FROM lego_inventory_parts lip
JOIN lego_inventories i ON i.id = lip.inventory_id
JOIN lego_sets s ON s.set_num = i.set_num
WHERE s.theme_id = 18
ORDER BY lip.inventory_id LIMIT 5;

-- Query 5: Query reference table lego_themes should show all themes
SELECT * FROM lego_themes ORDER BY id LIMIT 5;

RESET ROLE;"}

